            es_laboratorio=True,
            codigo_rechazo=None,
            procedencia=procedencia,
            extraccion=ResultadoExtraccion(
                campos=(
                    ResolucionCampo(codigo="marcador_laboratorio_alfa", estado=estado),
                ),
                procedencia=procedencia,
            ),
        )

